function kitStatus(status){return {fresh:'Ready to load',loaded:'Sample loaded',inserted:'In place',running:'Testing',used:'Used',removed:'Removed'}[status]||status;}

function connectedParts(id){
 const normalized=/^bay-\d+$/.test(id)?'bays':id.startsWith('reaction:')?'wells':id,seen=new Set(),items=[];
 for(const link of connectionFor(id)||[]){
  if(link.id==='cluster-data-link'){if(lab.config===16)items.push(`<p>Connected to Unit ${lab.selectedBay>8?1:2} to share test records. Each machine has its own power and moving parts.</p>`);continue;}
  for(const target of [link.from,link.to]){
   if(target===normalized)continue;const key=explanationMode?`${target}-${link.label}`:target;if(seen.has(key))continue;seen.add(key);
   const component=COMPONENTS.find(c=>c.id===target),name=component?partName(component):target;
   items.push(`<button data-linked-part="${esc(target)}"><strong>${esc(name)}</strong>${explanationMode?`<small>${esc(link.label)}</small>`:''}</button>`);
  }
 }
 return items.length?`<section class="connected-parts"><h4>Works with</h4>${items.join('')}</section>`:'';
}

function renderConnectionKey(){
 const el=$('#connection-key');el.hidden=!showConnections||!['inside','dock'].includes(view);if(el.hidden)return;
 const detailsOpen=!!el.querySelector('.bay-connection-details')?.open,dock=view==='dock',scope=dock?'dock':connectionScope,unit=lab.selectedBay>8?2:1;
 const descriptions={pressure:'Small drivers at each bay press against the outside of its cartridge. They do not touch the sample.',optical:'A light and camera read each cartridge. The images go to the machine for staff review.',data:'Each bay sends its test information to the screen. Every record stays linked to its patient and cartridge.',power:'The rear electrical connections supply each bay and its moving parts, heater, light and camera.'};
 const detail=dock?'The rails guide the cartridge into place. A lock holds it still while the drivers press against its dry outer pad. All liquid stays inside the cartridge.':descriptions[connectionKind]||'Every bay connects to power and data at the rear. Each has its own moving parts, heater and camera. Samples stay in their own cartridges.';
 const signature=JSON.stringify([scope,lab.config,lab.selectedBay,connectionKind,dockSeparated,explanationMode]);if(el.dataset.signature===signature)return;el.dataset.signature=signature;
 const plainKinds={pressure:'Movement',optical:'Light and camera',data:'Test information',power:'Power'};
 el.innerHTML=`<div class="connection-heading"><strong>${dock?`Bay ${lab.selectedBay}: cartridge fit`:scope==='system'?`How the bays connect${lab.config===16?` / Unit ${unit}`:''}`:`Bay ${lab.selectedBay}: connections`}</strong><span>Proposed design</span></div>
 <div class="connection-scope" role="group" aria-label="Connection view">${[['system','All bays'],['selected','This bay'],['dock','Cartridge fit']].map(([id,label])=>`<button data-connection-scope="${id}" aria-pressed="${scope===id}">${label}</button>`).join('')}</div>
 ${dock?`<div class="dock-controls"><button data-action="dock-separate" aria-pressed="${dockSeparated}">${dockSeparated?'Fit cartridge in place':'Show the contact points'}</button><span>${dockSeparated?'Cartridge moved out for a closer look.':'Cartridge aligned and locked in place.'} Your test keeps its current state.</span></div>`:`<div class="connection-types"><button data-connection-kind="all" aria-pressed="${!connectionKind}">Show all</button>${Object.entries(CONNECTION_KINDS).map(([kind,item])=>`<button data-connection-kind="${esc(kind)}" aria-pressed="${connectionKind===kind}"><i style="--connection-color:${esc(item.color)}"></i>${esc(explanationMode?item.label:plainKinds[kind]||item.label)}</button>`).join('')}</div>`}
 <p class="connection-description">${esc(detail)}</p>
 ${explanationMode?`<details class="bay-connection-details" ${detailsOpen?'open':''}><summary>Mechanical and electrical explanation</summary><div class="bay-route-summary"><div class="route-row"><strong>Movement</strong><span>Local motor driver and two dry linear actuators apply force through the silicone interface pad.</span></div><div class="route-row"><strong>Power and data</strong><span>Electrical connectors supply the bay electronics, heater and camera and carry identified test data.</span></div><div class="route-row"><strong>Sample</strong><span>Prepared patient and donor fractions remain in sealed disposable channels. No sample tubing connects bays.</span></div></div><p>${lab.config===16?'Each unit operates its own hardware. The inter-unit connection carries data only. ':''}This illustrates the proposed component arrangement. Mechanical travel, contact force and connector specifications still need validation.</p></details>`:''}`;
}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4000);}
function scenario(){return SCENARIOS.find(x=>x.id===state.scenarioId);}
function syncBay(){const session=selectedSession(lab);state=session.engine;const r=requirements(session).filter(x=>x.required);sampleLoaded=r.every(x=>x.loaded);inserted=session.loading.inserted;inserting=session.loading.inserting;insertionProgress=session.loading.insertionProgress;}
function operation(result){if(!result.ok)toast(result.reason);syncBay();render();return result.ok;}
function demo(){syncBay();const session=selectedSession(lab),d=deriveDemo(state,{sampleLoaded,inserted,inserting,explanationMode}),next=requirements(session).find(x=>x.required&&!x.loaded);
 if(session.kit.status==='removed'){return {...d,phase:'removed',title:'Prepare the next kit',instruction:'The used cartridge is out and its record is saved for review. Use a new cartridge for the next test.',action:'fresh-kit',actionLabel:'Prepare fresh cartridge',machine:{title:'Cartridge removed',status:'Bay ready for a fresh kit',lines:[`Bay ${session.bay}`,'Previous record retained','New cartridge required'],progress:0,tone:'neutral'}};}
 if(next&&!['blocked','review','authorised','handover'].includes(d.phase)){return {...d,phase:'loading',title:`Load ${next.label.toLowerCase()}`,instruction:next.description,action:'load-next',actionLabel:`Load ${next.label.toLowerCase()}`,machine:{title:'Load prepared samples',status:`Bay ${session.bay} / ${kitSummary(session).loadedCount} of ${kitSummary(session).requiredCount} loaded`,lines:[state.patient.id,`Next: ${next.label}`,'Test materials already inside'],progress:0,tone:'neutral'}};}
 return d;}
function bayName(session){if(session.engine.unavailableBays.includes(session.bay))return 'Unavailable';if(session.engine.running)return 'Testing';if(session.loading.inserting)return 'Inserting';if(session.kit.status==='removed')return 'Empty';if(session.kit.status==='used')return /Hold|Invalid/.test(session.engine.status)?'Investigate':'Result ready';if(session.engine.elapsed>0)return 'Paused';if(session.loading.inserted)return 'Ready to run';if(session.kit.status==='loaded')return 'Loading';return 'Available';}
function bayManager(){const total=labSummary(lab);return `<section class="bay-manager"><div class="bay-manager-heading"><h2>Testing bays</h2><button data-action="expand-bays" ${lab.config===16?'disabled':''}>${lab.config===8?'Connect another unit':'Add bays'}</button></div><div class="bay-grid ${lab.config>4?'many-bays':''}">${lab.sessions.map(x=>`<button class="bay-button" data-bay="${x.bay}" aria-pressed="${x.bay===lab.selectedBay}"><strong>Bay ${String(x.bay).padStart(2,'0')}</strong><small>${bayName(x)}</small>${x.engine.elapsed>0&&x.engine.elapsed<600?`<span class="bay-mini-progress"><i style="width:${x.engine.elapsed/6}%"></i></span>`:''}</button>`).join('')}</div><small>${total.running} testing / ${lab.config} installed bays${total.resultsWaiting?` / ${total.resultsWaiting} awaiting review`:''}</small></section>`;}

function dispatch(action){act(state,action);tickLab(lab,0);render();}
function selectScenario(id){const r=setScenario(lab,id);if(operation(r)){view='exterior';camera='reset';exploded=false;render();}}
function changeBay(bay){if(operation(selectBay(lab,Number(bay)))){camera=showConnections&&view==='inside'?'connections':'reset';partInfoVisible=false;render();}}
