function openReview(record=state){reviewRecord=record;note=record.reviewNote||'';operator=record.reviewer||operator||'';renderReview();$('#review-dialog').showModal();}

function renderReview(){
 microscope?.dispose();microscope=null;
 const record=reviewRecord||state,d=deriveDemo(record,{sampleLoaded:true,inserted:true,explanationMode}),rs=reactions(record),r=rs.find(x=>x.id===selectedReaction)||rs[0];selectedReaction=r.id;
 const evidenceOpen=!!$('#review-body .reaction-details')?.open;
 const complete=record.elapsed>=600,eligible=canAuthorise(record),evidence=describeEvidence(r,{explanationMode}),checks=qcChecks(record).map(x=>describeCheck(x,{explanationMode}));
 const results=Object.entries({ 'Blood group':d.result.group,...(record.cartridge!=='match'?{'Antibody check':d.result.screen}:{}),...(record.cartridge!=='type'?{'Donor check':d.result.crossmatch}:{})});
 $('#review-body').innerHTML=`<div class="dialog-heading"><div><span class="step-label">${esc(record.patient.id)} / ${esc(CARTRIDGES[record.cartridge].name)}</span><h2>Test results</h2></div><button data-action="close-review" aria-label="Close results">${icon('close')}</button></div><div class="review-layout"><section><div class="review-summary">${badge(d.machine.title,d.machine.tone)}<p>${esc(d.instruction)}</p><button class="text-button explanation-inline" data-action="explanation">${explanationMode?'Use plain language':'Explain these results'}</button></div>
 <dl class="result-values review-overview">${results.map(([label,value])=>`<div><dt>${label}</dt><dd>${esc(displayResult(value))}</dd></div>`).join('')}</dl>
 <details class="reaction-details" ${explanationMode||evidenceOpen?'open':''}><summary>${explanationMode?'Reaction evidence':'View individual test checks'} (${rs.length})</summary><div class="reaction-cards">${rs.map(x=>{const c=describeEvidence(x,{explanationMode});return `<button class="reaction-card ${x.id===selectedReaction?'active':''}" data-reaction="${x.id}"><span>${esc(c.title)}</span><strong>${esc(c.observation)}</strong></button>`;}).join('')}</div><div class="review-evidence"><div id="review-microscope"></div><div><h3>${esc(evidence.title)}</h3>${explanationMode?`<p>${esc(evidence.input)} tested with ${esc(evidence.reagent)}.</p>`:''}<strong>${esc(evidence.meaning)}</strong></div></div></details>
 <details class="technical-details" ${d.phase==='blocked'?'open':''}><summary>${explanationMode?'Quality control findings':'Safety and test checks'}</summary><div class="qc-list">${checks.map(x=>`<div class="qc-item"><strong>${esc(x.name)}</strong>${badge(x.status==='pass'?'Passed':x.status==='fail'?'Action required':'Pending',x.status==='fail'?'danger':x.status==='pass'?'success':'neutral')}<p>${esc(x.detail)}</p></div>`).join('')}</div></details></section>
 <aside class="review-actions"><h3>Staff review</h3><p>${eligible?'The test checks have passed. A qualified laboratory reviewer can approve this record.':!complete?'Let the test finish before reviewing the full result.':'A qualified laboratory reviewer must investigate the unresolved findings. This result cannot be approved.'}</p><label for="operator">Reviewer ID</label><input id="operator" value="${esc(operator)}" placeholder="Enter reviewer ID" maxlength="40"><label for="review-note">Review note</label><textarea id="review-note" rows="3">${esc(note)}</textarea><button class="primary-action" data-action="authorise" ${!eligible||!operator.trim()?'disabled':''}>${explanationMode?'Authorise result':'Approve result'}</button><button data-action="hold">Hold for investigation</button><button data-action="repeat" ${record!==state?'disabled title="Use an available bay to repeat a previous test"':''}>Repeat test</button><button data-action="handover" ${!record.authorised||!record.network||record.handedOver?'disabled':''}>Confirm ward received result</button><button class="text-button" data-action="report">Download record</button><p class="review-limits">${!record.network?'The hospital connection is unavailable. The result has not been sent.':'Result approval and ward receipt are separate from collecting blood and checking the patient at the bedside.'}</p></aside></div>`;
 if(r.ready){microscope=new ReactionViewer($('#review-microscope'));microscope.update({reaction:r});if(!explanationMode)$('#review-microscope canvas')?.setAttribute('aria-label',`Test image: ${evidence.observation}. Illustrative product image.`);}else $('#review-microscope').innerHTML='<div class="waiting-image">This image is not ready yet</div>';
}
function openDetails(){detailsMode='technical';renderDetails();$('#details-dialog').showModal();}

function renderDetails(){
 if(detailsMode==='lifecycle'){renderLifecycle();return;}
 const checks=qcChecks(state).map(x=>describeCheck(x,{explanationMode}));
 $('#details-body').innerHTML=`<div class="dialog-heading"><div><span class="step-label">${explanationMode?'EXPLANATION MODE':'TEST CHECKS'}</span><h2>Checks and activity</h2></div><button data-action="close-details" aria-label="Close test checks">${icon('close')}</button></div><div class="dialog-content">${explanationMode?`<p>Choose an issue to see how the machine responds. A test affected by a fault needs a fresh cartridge and a repeat run.</p><div class="fault-grid">${FAULTS.map(f=>`<label class="fault-toggle"><input type="checkbox" data-fault="${f.id}" ${state.faults.includes(f.id)?'checked':''}><span>${esc(f.name)}</span></label>`).join('')}<label class="fault-toggle"><input id="network-fault" type="checkbox" ${!state.network?'checked':''}><span>Disconnect hospital network</span></label></div><details class="technical-details"><summary>Event record</summary><div class="event-list">${[...state.audit].reverse().map(x=>`<p>${esc(x.event).replace(/simulated/gi,'demonstration').replace(/simulation/gi,'demonstration')}</p>`).join('')}</div></details>`:`<div class="qc-list">${checks.map(x=>`<div class="qc-item"><strong>${esc(x.name)}</strong>${badge(x.status==='pass'?'Passed':x.status==='fail'?'Action required':'Pending',x.status==='fail'?'danger':x.status==='pass'?'success':'neutral')}<p>${esc(x.detail)}</p></div>`).join('')}</div>`}</div>`;
}
function load(id){const next=id||requirements(selectedSession(lab)).find(x=>x.required&&!x.loaded)?.id;if(!next)return;const r=loadFraction(lab,next);if(operation(r)&&next==='patient-plasma')toast('Patient plasma loaded. It stays separate from the red cells until the required tests.');}
function insert(){const session=selectedSession(lab),result=insertKit(lab);if(!result.ok){operation(result);return;}session.loading.inserted=false;session.loading.inserting=true;session.loading.insertionProgress=0;const token=(session.animationToken||0)+1;session.animationToken=token;render();const start=performance.now();function animate(now){if(token!==session.animationToken)return;session.loading.insertionProgress=Math.min(1,(now-start)/1500);updateModel();if(session.loading.insertionProgress<1)requestAnimationFrame(animate);else{session.loading.inserted=true;session.loading.inserting=false;render();toast(`Cartridge locked in bay ${session.bay}. Ready to run.`);}}requestAnimationFrame(animate);}
function reset(){const session=selectedSession(lab),kit=kitSummary(session);if(kit.status==='removed'){operation(freshKit(lab));return;}if(kit.canUnload){operation(unloadKit(lab));return;}if(session.engine.running){toast('Pause or complete this test before clearing its cartridge.');return;}operation(freshKit(lab));}
function run(){operation(startBay(lab));}

function partDefinition(id){
 const component=COMPONENTS.find(x=>x.id===id);if(component)return component;
 if(/^bay-\d+$/.test(id))return {name:`Testing bay ${id.slice(4)}`,simpleName:`Bay ${id.slice(4)}`,simpleDoes:'Holds one cartridge and runs its test. Other bays can keep working at the same time.',does:'This bay accepts one identified single-use cartridge and runs independently.',why:'Other occupied bays continue while this bay is loaded or reviewed.',process:'Each test retains its own sample identifiers, kit and result record.'};
 if(id.startsWith('reaction:')){const r=reactions(state).find(x=>x.id===id.slice(9));if(r){const plain=describeEvidence(r,{explanationMode:false});return {name:r.name,simpleName:plain.title,simpleDoes:plain.meaning,does:`${r.input} is tested with ${r.reagent}.`,why:r.kind==='typing'?'This chamber contributes to blood grouping.':r.kind==='control'?'The reference response must match its expected pattern.':r.kind==='crossmatch'?'Patient plasma is tested against cells from the identified donor.':'Screening cells test for unexpected red-cell antibodies.',process:r.ready?r.interpretation:'This chamber has not been read yet.'};}}
 return {name:'Selected part',simpleName:'Selected part',simpleDoes:'Choose a named part to find out what it does.',does:'Select a labelled part to inspect its role.'};
}

function renderPartInfo(){
 const el=$('#part-info');el.hidden=!partInfoVisible;if(!partInfoVisible)return;
 const c=partDefinition(selectedComponent),sig=JSON.stringify([selectedComponent,lab.selectedBay,selectedSession(lab).kit.id,stageOf(state),showConnections,connectionKind,connectionScope,dockSeparated,explanationMode,c]);if(el.dataset.signature===sig)return;el.dataset.signature=sig;
 el.innerHTML=`<div class="part-info-panel"><div><h3>${esc(partName(c))}</h3><button data-action="close-part" aria-label="Close part information">${icon('close',16)}</button></div><p>${esc(partDescription(c))}</p>${explanationMode?`${c.why?`<p>${esc(c.why)}</p>`:''}${c.process?`<p>${esc(c.process)}</p>`:''}${c.dimension?`<strong>${esc(c.dimension)}</strong>`:''}`:''}${connectedParts(selectedComponent)}${!explanationMode?'<button class="text-button explanation-inline" data-action="explanation">Show the explanation</button>':''}</div>`;
}
function explainPart(id){if(/^bay-\d+$/.test(id)){changeBay(Number(id.slice(4)));}selectedComponent=id;partInfoVisible=true;if(section==='explore'&&!/^bay-\d+$/.test(id))renderControls();renderScene();}
function openLifecycle(){detailsMode='lifecycle';renderLifecycle();$('#details-dialog').showModal();}

function renderLifecycle(){
 const kit=kitSummary(selectedSession(lab));
 $('#details-body').innerHTML=`<div class="dialog-heading"><div><span class="step-label">AFTER USE</span><h2>What do I replace?</h2></div><button data-action="close-details" aria-label="Close after-use guide">${icon('close')}</button></div><div class="lifecycle-content"><p class="lifecycle-intro">Use a new cartridge and transfer tips for each test. Keep the machine and its testing bays.</p><ol class="lifecycle-steps"><li><strong>Keep used liquid inside</strong><p>The sample and used test materials stay sealed inside the cartridge.</p></li><li><strong>Keep the test record</strong><p>Patient and donor details, test images and staff review stay linked to the cartridge number.</p></li><li><strong>Discard the cartridge and tips</strong><p>Use the laboratory's waste process. Do not refill or reuse a used cartridge or transfer tip.</p></li><li><strong>Prepare the next test</strong><p>After the required checks, load prepared samples into a new cartridge. The screen, cameras, lights, heaters and moving parts are reused.</p></li></ol><section class="lifecycle-next"><h3>Checking another donor</h3><p>When the patient's earlier tests are still valid and reviewed, Match Only checks the next donor using patient plasma and that donor's red cells.</p></section><p class="lifecycle-current">Current cartridge: <strong id="lifecycle-kit-id">${esc(kit.id)}</strong> / <span id="lifecycle-kit-status">${esc(kitStatus(kit.status))}</span></p>${explanationMode?`<details class="technical-details"><summary>Design and procedure notes</summary><p>The proposed reusable bay uses dry mechanical actuators. The sample-contact channels, assay materials and contained waste remain in the single-use cartridge. Preparation, volumes, containment and maintenance require validation and hospital procedures.</p></details>`:''}</div>`;
}
function changeView(next){view=next;camera='reset';selectedComponent=next==='cartridge'?'cartridge':next==='optics'?'optics':next==='inside'?'pumps':'enclosure';render();}
function switchSection(next){section=next;history.replaceState(null,'',`#${section}`);if(section==='demonstrate'&&view==='optics')view='exterior';render();}
function downloadRecord(){const record=reviewRecord||state,stored=lab.sessions.flatMap(x=>x.history).find(x=>x.engine===record),kitId=stored?.kit.id||selectedSession(lab).kit.id;const lines=['HEMATRIX TEST RECORD','Product demonstration record. Not a clinical report.','',`Patient: ${record.patient.id}`,`Bay: ${record.bay||lab.selectedBay}`,`Kit ID: ${kitId}`,`Cartridge: ${CARTRIDGES[record.cartridge].name}`,`Status: ${deriveDemo(record,{sampleLoaded:true,inserted:true,explanationMode}).machine.title}`,`Reviewer: ${record.reviewer||'Awaiting review'}`,...reactions(record).map(x=>{const c=describeEvidence(x,{explanationMode});return `${c.title}: ${c.meaning}`;}),'',...qcChecks(record).map(x=>{const c=describeCheck(x,{explanationMode});return `${c.name}: ${c.status}`;})];const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([lines.join('\n')],{type:'text/plain'}));a.download=`HemaTrix_${record.patient.id}_record.txt`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}

$('#app').addEventListener('click',async e=>{
 const b=e.target.closest('button');if(!b||b.disabled)return;
 if(b.dataset.connectionScope){const next=b.dataset.connectionScope;showConnections=true;partInfoVisible=false;if(next==='dock'){view='dock';camera='reset';connectionKind=null;showLabels=true;selectedComponent='bay-dock';}else{connectionScope=next;view='inside';camera='connections';}render();return;}if(b.dataset.connectionKind){connectionKind=b.dataset.connectionKind==='all'?null:b.dataset.connectionKind;renderScene();return;}if(b.dataset.linkedPart){showConnections=true;connectionKind=null;const target=COMPONENTS.find(c=>c.id===b.dataset.linkedPart);if(target?.view==='inside')connectionScope='system';view=target?.view==='dock'?'dock':'inside';camera=view==='dock'?'reset':'connections';if(view==='dock')showLabels=true;explainPart(b.dataset.linkedPart);return;}if(b.dataset.bay){changeBay(b.dataset.bay);return;}if(b.dataset.fraction){load(b.dataset.fraction);return;}if(b.dataset.component){explainPart(b.dataset.component);return;}if(b.dataset.history!==undefined){openReview(selectedSession(lab).history[Number(b.dataset.history)].engine);return;}if(b.dataset.nav){switchSection(b.dataset.nav);return;}if(b.dataset.view){changeView(b.dataset.view);return;}if(b.dataset.reaction){selectedReaction=b.dataset.reaction;operator=$('#operator')?.value||operator;note=$('#review-note')?.value||note;renderReview();return;}
 const a=b.dataset.action;
 if(a==='explanation'){operator=$('#operator')?.value||operator;note=$('#review-note')?.value||note;explanationMode=!explanationMode;render();return;}
 if(a==='load'||a==='load-next'){load();return;}if(a==='insert'){insert();return;}if(a==='start'){run();return;}if(a==='resume'){state.running?operation(pauseBay(lab)):run();return;}
 if(a==='dock-separate'){dockSeparated=!dockSeparated;renderScene();return;}if(a==='connections'){showConnections=!(showConnections&&['inside','dock'].includes(view));if(showConnections){view='inside';connectionScope='system';camera='connections';}else if(view==='dock'){view='inside';camera='reset';}render();return;}if(a==='reset'){reset();return;}if(a==='expand-bays'){const next=[2,4,8,16].find(n=>n>lab.config);if(next)operation(configureLab(lab,next));return;}if(a==='labels'){showLabels=!showLabels;renderScene();return;}if(a==='dimensions'){showDimensions=!showDimensions;renderScene();return;}if(a==='close-part'){partInfoVisible=false;renderScene();return;}if(a==='unload-kit'){operation(unloadKit(lab));return;}if(a==='fresh-kit'){operation(freshKit(lab));return;}if(a==='lifecycle'){openLifecycle();return;}if(a==='review'){openReview();return;}if(a==='details'){openDetails();return;}
 if(a==='close-review'){$('#review-dialog').close();reviewRecord=null;return;}if(a==='close-details'){$('#details-dialog').close();return;}
 if(a==='screen-view'){view='exterior';camera='screen';render();viewer.setView('screen');return;}if(a==='close-screen'){camera='reset';viewer.setView('reset');renderScene();return;}
 if(a==='reset-camera'){camera='reset';viewer.setView('reset');$('#camera').value='reset';renderScene();return;}
 if(a==='fullscreen'){try{document.fullscreenElement?await document.exitFullscreen():await document.documentElement.requestFullscreen();}catch{toast('Full screen is not available in this browser.');}return;}
 if(a==='explode'){exploded=!exploded;render();return;}
 if(a==='flow-play'){inspectionFlow=true;inspectionPlaying=!inspectionPlaying;if(inspectionElapsed>=600)inspectionElapsed=0;render();return;}
 if(a==='flow-reset'){inspectionFlow=true;inspectionPlaying=false;inspectionElapsed=0;render();return;}
 if(['authorise','hold'].includes(a)){operator=$('#operator').value.trim();note=$('#review-note').value;if(!operator){toast('Enter a reviewer ID.');return;}act(reviewRecord||state,{type:'review',decision:a,operator,note});tickLab(lab,0);render();return;}
 if(a==='repeat'){if(reviewRecord&&reviewRecord!==state){toast('Use an available bay and a fresh kit to repeat a retained record.');return;}$('#review-dialog').close();reviewRecord=null;const kit=kitSummary(selectedSession(lab));if(kit.canUnload)operation(unloadKit(lab));else if(kit.status==='removed')operation(freshKit(lab));else toast('Complete or pause the active run before replacing its kit.');return;}
 if(a==='handover'){act(reviewRecord||state,{type:'handover'});render();return;}if(a==='report'){downloadRecord();return;}
});
$('#app').addEventListener('change',e=>{
 const t=e.target;
 if(t.id==='scenario'){selectScenario(t.value);return;}
 if(t.id==='cartridge'||t.id==='explore-cartridge'){operation(setCartridge(lab,t.value));return;}
 if(t.id==='donor'){operation(setDonor(lab,t.value));return;}
 if(t.id==='speed'){speed=Number(t.value);return;}
 if(t.id==='camera'){camera=t.value;if(camera==='connections'){showConnections=true;view='inside';}viewer.setView(camera);renderScene();return;}
 if(t.id==='component'){selectedComponent=t.value;const component=COMPONENTS.find(c=>c.id===t.value);view=component?.view||(['cartridge','inlet','channels','reagents','wells','waste','donor','patient-cells','patient-plasma','donor-cells'].includes(t.value)||t.value.startsWith('reaction:')?'cartridge':t.value==='optics'?'optics':'inside');camera='reset';if(view==='dock'){showConnections=true;showLabels=true;}else if(component?.view==='inside'){showConnections=true;connectionScope='system';camera='connections';}render();return;}
 if(t.id==='config'){operation(configureLab(lab,Number(t.value)));return;}
 if(t.id==='pattern'){pattern=t.value;renderControls();return;}if(t.id==='processed'){processed=t.checked;renderControls();return;}
 if(t.dataset.fault){act(state,{type:'fault',id:t.dataset.fault,enabled:t.checked});tickLab(lab,0);render();return;}
 if(t.id==='network-fault'){dispatch({type:'network',connected:!t.checked});return;}
});
$('#app').addEventListener('input',e=>{
 if(e.target.id==='inspection-position'){inspectionFlow=true;inspectionPlaying=false;inspectionElapsed=Number(e.target.value);updateModel();}
 if(e.target.id==='operator'){operator=e.target.value;const b=$('[data-action="authorise"]');if(b)b.disabled=!canAuthorise(reviewRecord||state)||!operator.trim();}
 if(e.target.id==='review-note')note=e.target.value;
});
