viewer=new ProductViewer($('#viewer'),{onSelect:id=>explainPart(id)});
const physicalScreen=document.createElement('div');physicalScreen.id='machine-screen';physicalScreen.className='physical-screen';physicalScreen.setAttribute('role','group');physicalScreen.setAttribute('aria-label','Machine display');$('#viewer').appendChild(physicalScreen);
const partLabels=document.createElement('div');partLabels.id='part-labels';$('#viewer').appendChild(partLabels);const dimensionLines=document.createElementNS('http://www.w3.org/2000/svg','svg');dimensionLines.id='dimension-lines';dimensionLines.setAttribute('aria-hidden','true');$('#viewer').appendChild(dimensionLines);const dimensionLabels=document.createElement('div');dimensionLabels.id='dimension-labels';$('#viewer').appendChild(dimensionLabels);
let lastAnnotation=0,annotationSignature='';
function updateAnnotations(){const width=$('#viewer').clientWidth,height=$('#viewer').clientHeight;partLabels.hidden=!showLabels;dimensionLabels.hidden=!showDimensions;dimensionLines.hidden=!showDimensions;if(!showLabels&&!showDimensions)return;const used=[];let labels='',leaders='';if(showLabels){for(const part of viewer.labelAnchors?.()||[]){if(!part.visible)continue;if(showConnections&&view==='inside'){const ids=new Set(CONNECTIONS.filter(link=>link.kind!=='manual'&&(!connectionKind||link.kind===connectionKind)).flatMap(link=>[link.from,link.to,...(Array.isArray(link.via)?link.via:[link.via])].filter(Boolean)));const id=/^bay-\d+$/.test(part.id)?'bays':part.id;if(!ids.has(id)||(connectionScope==='selected'&&/^bay-\d+$/.test(part.id)&&Number(part.id.slice(4))!==lab.selectedBay))continue;}const w=Math.min(width<500?180:220,Math.max(86,part.name.length*7.1+22)),h=part.name.length>24?44:34;const candidates=[[0,-24],[0,24],[85,0],[-85,0],[0,-52],[0,52],[120,-40],[-120,40]];let best,score=Infinity;for(const [dx,dy] of candidates){const cx=Math.max(w/2+6,Math.min(width-w/2-6,part.x+dx)),cy=Math.max(h/2+6,Math.min(height-h/2-6,part.y+dy));let overlap=0;for(const r of used)overlap+=Math.max(0,(r.w+w)/2-Math.abs(r.x-cx))*Math.max(0,(r.h+h)/2-Math.abs(r.y-cy));const rank=overlap*20+Math.abs(dx)+Math.abs(dy);if(rank<score){score=rank;best={x:cx,y:cy,w,h};}}used.push(best);leaders+=`<line x1="${part.x}" y1="${part.y}" x2="${best.x}" y2="${best.y}" stroke="#87928b" stroke-width="1"/>`;labels+=`<button class="part-label" data-component="${esc(part.id)}" style="left:${Math.round(best.x)}px;top:${Math.round(best.y)}px;width:${w}px;min-height:${h}px" title="${esc(part.name)}">${esc(part.name)}</button>`;}}const dims=showDimensions?(viewer.dimensionAnchors?.()||[]):[];let dimHtml='',lines='';for(const item of dims){if(!item.visible)continue;dimHtml+=`<span class="dimension-label" style="left:${Math.round(item.x)}px;top:${Math.round(item.y)}px">${esc(item.text)}</span>`;if(item.line)lines+=`<line x1="${item.line.x1}" y1="${item.line.y1}" x2="${item.line.x2}" y2="${item.line.y2}" stroke="#414844" stroke-width="1.3"/><path d="M${item.line.x1-4} ${item.line.y1-4}l8 8M${item.line.x2-4} ${item.line.y2-4}l8 8" stroke="#414844" fill="none"/>`;}
const sig=labels+'|'+leaders+'|'+dimHtml+'|'+lines;if(sig!==annotationSignature){annotationSignature=sig;partLabels.innerHTML=`<svg viewBox="0 0 ${width} ${height}" aria-hidden="true">${leaders}</svg>`+labels;dimensionLabels.innerHTML=dimHtml+(showDimensions?`<span class="dimension-note">${view==='cartridge'?'Cartridge size is not yet specified. Select Machine to see the Core size.':view==='optics'?'Individual camera and light sizes are not yet specified.':view==='dock'?'Cartridge holder and connector sizes are not yet specified.':lab.config>2?'Size shown is for the two-bay Core. Larger sizes are not yet specified.':'Proposed Core size. Final measurements are not yet available.'}</span>`:'');dimensionLines.setAttribute('viewBox',`0 0 ${width} ${height}`);dimensionLines.innerHTML=lines;}}

function anchorScreen(){const now=performance.now();if(now-lastAnnotation>90){lastAnnotation=now;updateAnnotations();}const q=viewer.screenAnchor?.(),el=$('#machine-screen');if(!q?.visible||view==='inside'||view==='cartridge'||view==='optics'){el.hidden=true;}else{el.hidden=false;const [p0,p1,p2,p3]=[q.corners[1],q.corners[2],q.corners[3],q.corners[0]],dx1=p1.x-p2.x,dx2=p3.x-p2.x,dx3=p0.x-p1.x+p2.x-p3.x,dy1=p1.y-p2.y,dy2=p3.y-p2.y,dy3=p0.y-p1.y+p2.y-p3.y,den=dx1*dy2-dx2*dy1;let g=0,h=0;if(Math.abs(den)>1e-8){g=(dx3*dy2-dx2*dy3)/den;h=(dx1*dy3-dx3*dy1)/den;}const a=p1.x-p0.x+g*p1.x,b=p3.x-p0.x+h*p3.x,d=p1.y-p0.y+g*p1.y,e=p3.y-p0.y+h*p3.y;el.style.transform=`matrix3d(${a/640},${d/640},0,${g/640},${b/226},${e/226},0,${h/226},0,0,1,0,${p0.x},${p0.y},0,1)`;}requestAnimationFrame(anchorScreen);}
render();anchorScreen();
let last=performance.now();
setInterval(()=>{const now=performance.now(),dt=Math.min(1,(now-last)/1000);last=now;let changed=false;if(lab.sessions.some(x=>x.engine.running)){tickLab(lab,dt*speed);syncBay();changed=true;}if(inspectionPlaying&&section==='explore'){inspectionElapsed=Math.min(600,inspectionElapsed+dt*50);if(inspectionElapsed>=600)inspectionPlaying=false;const range=$('#inspection-position');if(range)range.value=inspectionElapsed;changed=true;}if(changed){renderScene();const d=demo(),sig=[section,lab.selectedBay,d.phase,state.status,stageOf(state),inspectionPlaying,lab.sessions.map(x=>x.kit.status).join('-')].join('|');if(sig!==lastSideSignature){lastSideSignature=sig;renderControls();if($('#review-dialog').open)renderReview();}}},120);
window.addEventListener('hashchange',()=>{section=location.hash==='#explore'?'explore':'demonstrate';render();});
window.addEventListener('beforeunload',()=>{viewer.dispose();microscope?.dispose();opticalViewer?.dispose();});
